"""Detect and screen S4 DAS events with balanced nuisance-reference sampling."""
from __future__ import annotations
import base64
import gzip
import hashlib
import json
import sys
import types
from pathlib import Path
REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
from typing import Callable
import numpy as np
import pandas as pd
ROOT = REPOSITORY_ROOT
S4_H5_INPUT_DIR = REPOSITORY_ROOT / 'data/raw/S4'
S4_INPUT_DIR = REPOSITORY_ROOT / 'data/screening_inputs/S4'
S4_OUTPUT_DIR = REPOSITORY_ROOT / 'outputs/screening/S4'
_EMBEDDED_S2_CORE_SHA256 = 'e46e460f76a32ba953908e3d62e23a32228e4cfa22a6e395bc8094d20f6341a4'
_EMBEDDED_S2_CORE_B64 = ''
PRECURSOR_CUTOFF = pd.Timestamp('2025-08-11 20:28:46')
MACRO_OBSERVATION = pd.Timestamp('2025-08-11 20:29:07')
MACRO_TRANSITION_END = pd.Timestamp('2025-08-11 20:29:24')
ANALYSIS_END = pd.Timestamp('2025-08-11 20:30:00')
MAX_SCALE_S = 2.0
REFERENCE_SAFE_END = PRECURSOR_CUTOFF - pd.Timedelta(seconds=MAX_SCALE_S / 2)
CANDIDATE_FEATURE_SAFE_END = ANALYSIS_END - pd.Timedelta(seconds=MAX_SCALE_S / 2)
DEFAULT_REFERENCE_FAMILY_PLAN = {'stable_rain': [{'family': 'stable_early_rain', 'quota': 240, 'reference_classes': ['stable_hydraulic_background']}], 'personnel': [{'family': 'adult_personnel', 'quota': 90, 'kinds': ['personnel']}, {'family': 'children_voice', 'quota': 90, 'kinds': ['children_voice']}], 'pumping': [{'family': 'pumping_and_mixed_operation', 'quota': 80, 'kinds': ['pumping', 'mixed_personnel_pumping', 'mixed_pumping_vehicle']}, {'family': 'rain_impact', 'quota': 60, 'kinds': ['rain_impact']}, {'family': 'vehicle_and_loudspeaker', 'quota': 40, 'kinds': ['tractor', 'vehicle_horn', 'vendor_loudspeaker']}, {'family': 'scanner_mechanical', 'quota': 40, 'kinds': ['scanner', 'scanner_vehicle']}, {'family': 'metal_impact', 'quota': 20, 'kinds': ['metal_impact']}]}

def load_s2_adapter():
    """Load the complete S2 screening core embedded in this S4 file."""
    try:
        source = gzip.decompress(base64.b64decode(_EMBEDDED_S2_CORE_B64)).decode('utf-8')
    except Exception as exc:
        raise RuntimeError('Unable to decode the embedded S2 screening core.') from exc
    digest = hashlib.sha256(source.encode('utf-8')).hexdigest()
    if digest != _EMBEDDED_S2_CORE_SHA256:
        raise RuntimeError('Embedded S2 screening core failed its SHA-256 integrity check.')
    module_name = 's4_embedded_s2_screening_core'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    exec(compile(source, '<embedded S2 standalone screening core>', 'exec'), module.__dict__)
    module.S4_IMPORTED_S2_SOURCE = '<embedded S2 standalone screening core>'
    return module

def load_s4_config() -> dict:
    path = S4_INPUT_DIR / 'S4_screening_configuration.json'
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding='utf-8'))

def read_s4_inputs(config: dict) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame, dict]:
    metadata = pd.read_csv(S4_INPUT_DIR / 'S4_monitoring_channel_layout.csv')
    stages = pd.read_csv(S4_INPUT_DIR / 'S4_process_stage_blocks.csv')
    windows = pd.read_csv(S4_INPUT_DIR / 'S4_background_reference_windows.csv')
    nuisance = pd.read_csv(S4_INPUT_DIR / 'S4_known_nuisance_intervals.csv')
    for frame in (stages, windows, nuisance):
        for column in ('start_time', 'end_time', 'center_time'):
            if column in frame:
                frame[column] = pd.to_datetime(frame[column], format='mixed')
    metadata['data_channel'] = pd.to_numeric(metadata['data_channel'], errors='raise').astype(int)
    metadata['burial_depth_cm'] = pd.to_numeric(metadata['burial_depth_cm'], errors='raise')
    metadata['geometry_type'] = metadata['geometry_type'].astype(str).str.lower()
    mapping = config.get('noise_type_to_algorithm_class', {})
    actual_kind = nuisance['kind'].astype(str).str.strip().str.lower()
    unknown = sorted(set(actual_kind) - set(mapping))
    if unknown:
        raise ValueError(f'S4 nuisance types lack an S2 algorithm mapping: {unknown}')
    nuisance['actual_kind'] = actual_kind
    nuisance['kind'] = actual_kind.map(mapping)
    if not nuisance['kind'].isin(['personnel', 'pumping']).all():
        raise ValueError('S4 nuisance mapping must resolve only to personnel or pumping.')
    return (metadata, stages, windows, nuisance, config)

def validate_reference_family_plan(plan: dict, counts: dict, noise_mapping: dict, actual_kinds) -> None:
    """Reject incomplete, duplicated or cross-class S4 subtype plans."""
    required_labels = ('stable_rain', 'personnel', 'pumping')
    seen: dict[str, str] = {}
    for label in required_labels:
        families = plan.get(label, [])
        if not families:
            raise ValueError(f'Balanced reference plan has no family for {label!r}.')
        quota_sum = sum((int(spec['quota']) for spec in families))
        if quota_sum != int(counts[label]):
            raise ValueError(f'Balanced reference quotas for {label!r} sum to {quota_sum}, but reference_counts requires {counts[label]}.')
        if label == 'stable_rain':
            continue
        for spec in families:
            family = str(spec['family'])
            for raw_kind in spec.get('kinds', []):
                kind = str(raw_kind).strip().lower()
                if kind in seen:
                    raise ValueError(f'S4 nuisance type {kind!r} occurs in both {seen[kind]!r} and {family!r}.')
                mapped = noise_mapping.get(kind)
                if mapped != label:
                    raise ValueError(f'S4 nuisance type {kind!r} is planned under {label!r}, but maps to {mapped!r}.')
                seen[kind] = family
    expected = {str(value).strip().lower() for value in actual_kinds}
    planned = set(seen)
    missing = sorted(expected - planned)
    extra = sorted(planned - expected)
    if missing or extra:
        raise ValueError(f'Balanced S4 nuisance-family coverage is inconsistent: missing={missing}, extra={extra}.')

def configure_s2_adapter_for_s4(adapter) -> tuple[dict, pd.DataFrame]:
    config = load_s4_config()
    adapter.WORK_DIR = ROOT
    adapter.S2_INPUT_DIR = S4_INPUT_DIR
    adapter.H5_INPUT_DIR = S4_H5_INPUT_DIR
    adapter.OUTPUT_DIR = S4_OUTPUT_DIR
    adapter.FIGURE_DIR = adapter.OUTPUT_DIR / 'paper_figures_A4'
    adapter.REVIEW_DIR = adapter.OUTPUT_DIR / 'manual_review_panels'
    adapter.LAYOUT_CSV = S4_INPUT_DIR / 'S4_monitoring_channel_layout.csv'
    adapter.STAGE_CSV = S4_INPUT_DIR / 'S4_process_stage_blocks.csv'
    adapter.REFERENCE_WINDOW_CSV = S4_INPUT_DIR / 'S4_background_reference_windows.csv'
    adapter.NUISANCE_CSV = S4_INPUT_DIR / 'S4_known_nuisance_intervals.csv'
    adapter.CONFIG_JSON = S4_INPUT_DIR / 'S4_screening_configuration.json'
    adapter.MACRO_OBSERVATION = PRECURSOR_CUTOFF
    adapter.ANALYSIS_END = ANALYSIS_END
    adapter.REFERENCE_SAFE_END = REFERENCE_SAFE_END
    adapter.CANDIDATE_FEATURE_SAFE_END = CANDIDATE_FEATURE_SAFE_END
    adapter.REFERENCE_COUNTS = {key: int(value) for key, value in config.get('reference_counts', {'stable_rain': 240, 'personnel': 180, 'pumping': 240}).items()}
    actual_nuisance = pd.read_csv(adapter.NUISANCE_CSV)
    actual_nuisance['start_time'] = pd.to_datetime(actual_nuisance['start_time'], format='mixed')
    actual_nuisance['end_time'] = pd.to_datetime(actual_nuisance['end_time'], format='mixed')
    actual_nuisance['kind'] = actual_nuisance['kind'].astype(str).str.lower()
    actual_nuisance['buffer_s'] = pd.to_numeric(actual_nuisance['buffer_s'], errors='raise').astype(float)

    def patched_read_inputs():
        return read_s4_inputs(config)
    adapter.read_s2_inputs = patched_read_inputs
    adapter.canonical_noise_kind = lambda kind: str(kind).lower()
    return (config, actual_nuisance)

def apply_s4_phase_tags(catalog: pd.DataFrame) -> pd.DataFrame:
    result = catalog.copy()
    peak = pd.to_datetime(result['peak_time'], errors='coerce')
    result['event_phase'] = np.select([peak.lt(PRECURSOR_CUTOFF), peak.le(MACRO_TRANSITION_END)], ['pre_macro', 'macro_transition'], default='post_macro')
    result['is_precursory_candidate'] = peak.lt(PRECURSOR_CUTOFF)
    result['seconds_from_macro_observation'] = (peak - MACRO_OBSERVATION).dt.total_seconds()
    return result

def nuisance_kinds_at(time: pd.Timestamp, nuisance: pd.DataFrame, buffered: bool) -> str:
    if pd.isna(time):
        return ''
    stamp = pd.Timestamp(time)
    kinds: list[str] = []
    for row in nuisance.itertuples(index=False):
        pad = pd.Timedelta(seconds=float(row.buffer_s)) if buffered else pd.Timedelta(0)
        if pd.Timestamp(row.start_time) - pad <= stamp <= pd.Timestamp(row.end_time) + pad:
            kinds.append(str(row.kind))
    return ';'.join(sorted(set(kinds)))

def install_s4_balanced_reference_sampling(base, actual_nuisance: pd.DataFrame, config: dict) -> None:
    """Balance KNN references by actual S4 subtype without changing S2 labels."""
    metadata, _, windows, _, _ = read_s4_inputs(config)
    counts = {key: int(value) for key, value in config.get('reference_counts', {'stable_rain': 240, 'personnel': 180, 'pumping': 240}).items()}
    plan = config.get('balanced_reference_sampling', {}).get('families', DEFAULT_REFERENCE_FAMILY_PLAN)
    required_labels = ('stable_rain', 'personnel', 'pumping')
    validate_reference_family_plan(plan, counts, config.get('noise_type_to_algorithm_class', {}), actual_nuisance['kind'])
    feature_h5_coverage_cache: list[tuple[pd.Timestamp, pd.Timestamp]] | None = None

    def get_feature_h5_coverage() -> list[tuple[pd.Timestamp, pd.Timestamp]]:
        nonlocal feature_h5_coverage_cache
        if feature_h5_coverage_cache is not None:
            return feature_h5_coverage_cache
        records = [record for record in base.refine.list_h5_records() if pd.Timestamp(record.start) < ANALYSIS_END]
        if not records:
            raise RuntimeError('No S4 H5 record is available before ANALYSIS_END.')
        coverage: list[tuple[pd.Timestamp, pd.Timestamp]] = []
        for record in records:
            start = pd.Timestamp(record.start)
            samples = int(getattr(record, 'samples', round(base.FILE_DURATION_S * base.SAMPLE_RATE_HZ)))
            end = start + pd.Timedelta(seconds=samples / base.SAMPLE_RATE_HZ)
            coverage.append((start, end))
        coverage.sort(key=lambda pair: pair[0])
        feature_h5_coverage_cache = coverage
        return coverage

    def time_is_inside_h5(time: pd.Timestamp, coverage: list[tuple[pd.Timestamp, pd.Timestamp]], margin_s: float=0.0) -> bool:
        stamp = pd.Timestamp(time)
        margin = pd.Timedelta(seconds=float(margin_s))
        return any((start + margin <= stamp < end - margin for start, end in coverage if (end - start).total_seconds() > 2.0 * margin_s))

    def available_times(intervals: pd.DataFrame) -> list[pd.Timestamp]:
        coverage = get_feature_h5_coverage()
        raw_context_s = float(getattr(base.refine, 'RAW_CONTEXT_S', 4.0))
        feature_margin_s = max(2.0, raw_context_s / 2.0 + 0.1)
        h5_edge = pd.Timedelta(seconds=5)
        values: list[pd.Timestamp] = []
        for row in intervals.itertuples(index=False):
            interval_start = pd.Timestamp(row.start_time) + pd.Timedelta(seconds=2)
            interval_end = min(pd.Timestamp(row.end_time) - pd.Timedelta(seconds=2), REFERENCE_SAFE_END)
            if interval_end <= interval_start:
                continue
            for h5_start, h5_end in coverage:
                grid = pd.date_range(h5_start + h5_edge, h5_end - h5_edge, freq='10s', inclusive='left')
                values.extend((pd.Timestamp(value) for value in grid if interval_start <= pd.Timestamp(value) <= interval_end))
        unique_by_ns = {pd.Timestamp(value).value: pd.Timestamp(value) for value in values}
        return [unique_by_ns[key] for key in sorted(unique_by_ns) if time_is_inside_h5(unique_by_ns[key], coverage, margin_s=feature_margin_s)]

    def intervals_for_family(label: str, spec: dict) -> pd.DataFrame:
        if label == 'stable_rain':
            classes = set(spec.get('reference_classes', []))
            return windows[windows['reference_class'].astype(str).isin(classes)].copy()
        kinds = set((str(value).lower() for value in spec.get('kinds', [])))
        return actual_nuisance[actual_nuisance['kind'].astype(str).str.lower().isin(kinds)].copy()
    allocation_audit: list[dict] = []

    def balanced_reference_times(label: str, count: int, rng: np.random.Generator, globally_selected: set[int]) -> pd.DatetimeIndex:
        entries: list[dict] = []
        for spec in plan[label]:
            family = str(spec['family'])
            intervals = intervals_for_family(label, spec)
            values = [value for value in available_times(intervals) if pd.Timestamp(value).value not in globally_selected]
            entries.append({'family': family, 'quota': int(spec['quota']), 'available': values, 'selected': []})
        selected_keys: set[int] = set()
        for entry in sorted(entries, key=lambda value: (len(value['available']), value['family'])):
            candidates = [value for value in entry['available'] if pd.Timestamp(value).value not in selected_keys]
            number = min(entry['quota'], len(candidates), count - len(selected_keys))
            if number:
                positions = np.atleast_1d(rng.choice(len(candidates), size=number, replace=False))
                chosen = [candidates[int(position)] for position in positions]
                entry['selected'].extend(chosen)
                selected_keys.update((pd.Timestamp(value).value for value in chosen))
        deficit = count - len(selected_keys)
        while deficit > 0:
            progressed = False
            for entry in entries:
                remaining = [value for value in entry['available'] if pd.Timestamp(value).value not in selected_keys]
                if remaining:
                    chosen = remaining[int(rng.integers(0, len(remaining)))]
                    entry['selected'].append(chosen)
                    selected_keys.add(pd.Timestamp(chosen).value)
                    deficit -= 1
                    progressed = True
                    if deficit == 0:
                        break
            if not progressed:
                break
        selected = [value for entry in entries for value in entry['selected']]
        if len(selected) != len(selected_keys):
            raise RuntimeError(f'Internal S4 reference uniqueness mismatch for {label!r}: rows={len(selected)}, unique_nanosecond_times={len(selected_keys)}.')
        replacement_count = count - len(selected)
        if replacement_count > 0:
            pool_by_ns = {pd.Timestamp(value).value: pd.Timestamp(value) for entry in entries for value in entry['available']}
            pool = [pool_by_ns[key] for key in sorted(pool_by_ns)]
            if not pool:
                raise RuntimeError(f'No H5-covered S4 reference time exists for {label!r}.')
            positions = np.atleast_1d(rng.choice(len(pool), size=replacement_count, replace=True))
            selected.extend((pool[int(position)] for position in positions))
        if len(selected) != count:
            raise RuntimeError(f'Balanced S4 reference sampling produced {len(selected)} rows for {label!r}; expected {count}.')
        globally_selected.update((pd.Timestamp(value).value for value in selected))
        for entry in entries:
            audit = {'algorithm_class': label, 'family': entry['family'], 'target_quota': entry['quota'], 'unique_available': len(entry['available']), 'allocated_without_replacement': len(entry['selected'])}
            allocation_audit.append(audit)
            base.log(f"[S4/reference-balance] {label}/{entry['family']}：目标={entry['quota']}；可用唯一时刻={len(entry['available'])}；无放回分配={len(entry['selected'])}")
        if replacement_count:
            base.log(f'[S4/reference-balance] {label}唯一时刻不足，最终有放回补足={replacement_count}。')
        return pd.DatetimeIndex(selected)

    def sample_sensors(count: int, rng: np.random.Generator) -> pd.DataFrame:
        targets = metadata[metadata['analysis_role'].eq('target')].copy()
        targets['stratum'] = targets['burial_depth_cm'].round(3).astype(str) + '|' + targets['geometry_type'].astype(str)
        groups = [group.reset_index(drop=True) for _, group in targets.groupby('stratum', sort=True)]
        if not groups:
            raise RuntimeError('S4 monitoring table has no target sensors.')
        return pd.DataFrame([groups[index % len(groups)].iloc[int(rng.integers(0, len(groups[index % len(groups)])))] for index in range(count)]).reset_index(drop=True)

    def build_feature_tasks_balanced(events: pd.DataFrame, table: pd.DataFrame, blocks: pd.DataFrame, max_events=None) -> pd.DataFrame:
        del table
        candidate = events.copy()
        if max_events is not None and len(candidate) > max_events:
            candidate = candidate.sort_values('peak_time').head(int(max_events)).copy()
        event_tasks = pd.DataFrame({'task_id': 'candidate:' + candidate['physical_event_id'].astype(str), 'task_class': 'candidate', 'physical_event_id': candidate['physical_event_id'].astype(str), 'time': pd.to_datetime(candidate['peak_time']), 'data_channel': candidate['representative_data_channel'].astype(int), 'geometry_type': candidate['geometry_type'].astype(str).str.lower(), 'burial_depth_cm': candidate['burial_depth_cm'].astype(float), 'segment_id': candidate['representative_segment_id'].astype(str), 'stage_id': candidate['stage_id'].astype(int)})
        rng = np.random.default_rng(base.RANDOM_SEED)
        globally_selected: set[int] = set()
        rows: list[dict] = []
        allocation_audit.clear()
        for label in required_labels:
            count = counts[label]
            times = balanced_reference_times(label, count, rng, globally_selected=globally_selected)
            sensors = sample_sensors(count, rng)
            stage_ids = base.stage_ids(times, blocks)
            for number, (time, sensor) in enumerate(zip(times, sensors.itertuples(index=False))):
                rows.append({'task_id': f'{label}:{number:05d}', 'task_class': label, 'physical_event_id': '', 'time': pd.Timestamp(time), 'data_channel': int(sensor.data_channel), 'geometry_type': str(sensor.geometry_type).lower(), 'burial_depth_cm': float(sensor.burial_depth_cm), 'segment_id': str(sensor.segment_id), 'stage_id': int(stage_ids[number])})
        tasks = pd.concat([event_tasks, pd.DataFrame(rows)], ignore_index=True)
        tasks['time'] = pd.to_datetime(tasks['time'], errors='coerce')
        coverage = get_feature_h5_coverage()
        covered = tasks['time'].map(lambda value: False if pd.isna(value) else time_is_inside_h5(pd.Timestamp(value), coverage, margin_s=0.0)).astype(bool)
        if not covered.all():
            bad = tasks.loc[~covered, ['task_id', 'task_class', 'time']]
            raise RuntimeError(f"Balanced S4 task validation failed: {len(bad)} tasks lie outside actual H5 coverage; examples={bad.head(10).to_dict('records')}")
        base.S4_REFERENCE_ALLOCATION_AUDIT = list(allocation_audit)
        base.log(f'[S4/reference-balance] H5覆盖校验通过：{len(tasks):,}/{len(tasks):,}个任务。')
        return tasks
    base.refine.build_feature_tasks = build_feature_tasks_balanced
    base.S4_BALANCED_REFERENCE_PLAN = plan
    base.S4_REFERENCE_ALLOCATION_AUDIT = []

def install_s4_output_semantics(base, original_readme: Callable, actual_nuisance: pd.DataFrame, config: dict) -> None:
    inherited_tagger = base.add_formal_screening_tags

    def add_formal_screening_tags(catalog: pd.DataFrame) -> pd.DataFrame:
        result = apply_s4_phase_tags(inherited_tagger(catalog))
        peak = pd.to_datetime(result['peak_time'], errors='coerce')
        result['exact_nuisance_kinds'] = peak.map(lambda value: nuisance_kinds_at(value, actual_nuisance, buffered=False))
        result['buffered_nuisance_kinds'] = peak.map(lambda value: nuisance_kinds_at(value, actual_nuisance, buffered=True))
        result['exact_nuisance_overlap'] = result['exact_nuisance_kinds'].ne('')
        result['buffered_nuisance_overlap'] = result['buffered_nuisance_kinds'].ne('')
        return result

    def write_method_readme(baseline_catalog: pd.DataFrame, four_catalog: pd.DataFrame) -> None:
        original_readme(baseline_catalog, four_catalog)
        note = {'experiment': 'S4_two_cracks_high_rainfall', 's2_core_source': str(getattr(sys.modules.get('s4_s2_screening_core'), 'S4_IMPORTED_S2_SOURCE', '')), 'analysis_end': ANALYSIS_END.isoformat(), 'first_visible_local_sliding_precursor_cutoff': PRECURSOR_CUTOFF.isoformat(), 'macro_observation_reference': MACRO_OBSERVATION.isoformat(), 'macro_transition_end': MACRO_TRANSITION_END.isoformat(), 'reference_safe_end': REFERENCE_SAFE_END.isoformat(), 'phase_policy': {'pre_macro': f'peak_time < {PRECURSOR_CUTOFF}', 'macro_transition': f'{PRECURSOR_CUTOFF} <= peak_time <= {MACRO_TRANSITION_END}', 'post_macro': f'peak_time > {MACRO_TRANSITION_END}'}, 'precursor_policy': 'Only pre_macro events may be described as precursory candidates.', 'calibration_policy': 'The macro-transition and post-macro stages use the final clean pre-transition stage model for detection only; they never enter calibration or KNN reference domains.', 'noise_policy': {'actual_labels_retained_in_catalog': True, 'algorithm_mapping': config.get('noise_type_to_algorithm_class', {}), 'reference_counts': config.get('reference_counts', {}), 'balanced_reference_sampling': config.get('balanced_reference_sampling', {'strategy': 'actual_subtype_quota_then_within_class_redistribution', 'allow_replacement_only_if_total_unique_times_are_insufficient': True, 'families': DEFAULT_REFERENCE_FAMILY_PLAN}), 'realized_allocation': getattr(base, 'S4_REFERENCE_ALLOCATION_AUDIT', [])}, 'time_basis': 'seconds_from_macro_observation is referenced to 2025-08-11 20:29:07.'}
        (base.OUTPUT_DIR / 'S4_run_interpretation.json').write_text(json.dumps(note, ensure_ascii=False, indent=2), encoding='utf-8')
    base.add_formal_screening_tags = add_formal_screening_tags
    base.write_method_readme = write_method_readme
    base.S4_REPORTED_MACRO_OBSERVATION = MACRO_OBSERVATION
    base.S4_MACRO_TRANSITION_END = MACRO_TRANSITION_END

def require_verified_h5_metadata_for_full_run(arguments: list[str]) -> None:
    mode = arguments[0].lower() if arguments else 'all'
    if mode == 'smoke':
        return
    config = load_s4_config()
    summary = config.get('h5_summary', {})
    configured_h5 = str(config.get('h5_input_dir', '')).rstrip('\\/').casefold()
    hardcoded_h5 = str(S4_H5_INPUT_DIR).rstrip('\\/').casefold()
    if configured_h5 != hardcoded_h5:
        raise RuntimeError('The H5 path recorded in S4_screening_configuration.json does not match the hard-coded S4_H5_INPUT_DIR. Rerun build_s4_screening_inputs.py --require-h5 after editing both files.')
    if summary.get('metadata_source') != 'verified_from_s4_h5_headers':
        raise RuntimeError('Full S4 screening requires H5-verified acquisition metadata. Run build_s4_screening_inputs.py --require-h5 --h5-dir <S4 raw H5 folder> first.')

def main() -> int:
    adapter = load_s2_adapter()
    config, actual_nuisance = configure_s2_adapter_for_s4(adapter)
    require_verified_h5_metadata_for_full_run(sys.argv[1:])
    adapter.require_inputs()
    base = adapter.load_s1_script()
    original_readme = base.write_method_readme
    adapter.install_s2_adapter(base)
    install_s4_balanced_reference_sampling(base, actual_nuisance, config)
    install_s4_output_semantics(base, original_readme, actual_nuisance, config)
    adapter.install_stage4_cache_repair(base)
    base.log('[S4] 前兆截止=20:28:46；宏观观察参考=20:29:07；过渡结束=20:29:24；分析截止=20:30:00')
    return int(base.main(sys.argv[1:]))
if __name__ == '__main__':
    raise SystemExit(main())
